con.execute("ATTACH 'query_dataset/sales_pipeline.duckdb' AS sales_pipeline (READ_ONLY)")
con.execute("ATTACH 'query_dataset/products_orders.db' AS products_orders (TYPE SQLITE, READ_ONLY)")
start="date '2022-11-25' - interval '5 months'"; end="date '2022-11-25'"
sql=f"""
with eligible_opp as (
 select regexp_replace(trim(o.Id),'^#','') oppid, regexp_replace(trim(o.AccountId),'^#','') accountid, regexp_replace(trim(o.OwnerId),'^#','') opp_agent, c.CompanySignedDate
 from sales_pipeline.Opportunity o join sales_pipeline.Contract c on regexp_replace(trim(o.ContractID__c),'^#','')=regexp_replace(trim(c.Id),'^#','')
 where cast(c.CompanySignedDate as date) >= {start} and cast(c.CompanySignedDate as date) <= {end}
), order_sales as (
 select regexp_replace(trim(ord.Id),'^#','') orderid, regexp_replace(trim(ord.AccountId),'^#','') accountid, regexp_replace(trim(ord.OwnerId),'^#','') order_agent, ord.EffectiveDate,
        sum(cast(oi.Quantity as double)*cast(oi.UnitPrice as double)) amount
 from products_orders."Order" ord join products_orders.OrderItem oi on regexp_replace(trim(oi.OrderId),'^#','')=regexp_replace(trim(ord.Id),'^#','')
 where cast(ord.EffectiveDate as date) >= {start} and cast(ord.EffectiveDate as date) <= {end}
 group by 1,2,3,4
)
select e.oppid,e.opp_agent,e.CompanySignedDate, os.orderid,os.order_agent,os.EffectiveDate,os.amount,e.accountid
from eligible_opp e join order_sales os using(accountid)
order by os.amount desc limit 20
"""
